/**
 * BackendSidecar — spawns the FastAPI backend as a child process, polls health.
 *
 * In dev: spawns the venv python (`venv/Scripts/python.exe` on Windows,
 * `venv/bin/python` on Unix) running `python -m backend.main`.
 * In prod: uses the PyInstaller binary registered as a Tauri sidecar.
 *
 * No token is generated by default — the backend runs in open mode.
 * Cookie-based YouTube auth is configured separately via the Auth page.
 *
 * P6: Separate reader threads for stdout/stderr (avoid pipe deadlock).
 * P7: encoding="utf-8", errors="replace" on subprocess pipes.
 */

import { Command, type Child, type TerminatedPayload } from "@tauri-apps/plugin-shell";

export type BackendStatus = "starting" | "running" | "stopped" | "error";

interface SidecarCallbacks {
  onStatusChange: (status: BackendStatus) => void;
  onLog: (line: string) => void;
}

const MAX_LOG_LINES = 1000;
const HEALTH_POLL_MS = 1000;

/**
 * Check if Tauri internals are available.
 * `window.__TAURI_INTERNALS__` is injected by the Tauri runtime; if it's
 * missing, `Channel` (used by plugin-shell's spawn) throws
 * "Cannot read properties of undefined (reading 'transformCallback')".
 */
function tauriInternalsReady(): boolean {
  return typeof window !== "undefined" && !!(window as any).__TAURI_INTERNALS__;
}

/** Resolve the venv python executable path. */
function venvPython(): string {
  // Windows: venv/Scripts/python.exe, Unix: venv/bin/python
  // The cwd is amp/ (parent of frontend/), so venv is at ../venv
  return "venv/Scripts/python.exe";
}

class BackendSidecar {
  private process: Child | null = null;
  private status: BackendStatus = "stopped";
  private healthTimer: ReturnType<typeof setInterval> | null = null;
  private logRing: string[] = [];
  private callbacks: SidecarCallbacks | null = null;
  private inFlightHealth = false; // P12: in-flight guard

  getStatus(): BackendStatus {
    return this.status;
  }

  getLogs(): string[] {
    return [...this.logRing];
  }

  async start(callbacks: SidecarCallbacks): Promise<void> {
    this.callbacks = callbacks;
    this._setStatus("starting");

    // If Tauri internals aren't ready, we can't spawn a sidecar.
    // Check if a backend is already running (e.g. from a previous session).
    if (!tauriInternalsReady()) {
      this._pushLog("Tauri internals not available — checking for existing backend...");
      const existing = await this._probeExistingBackend();
      if (existing) {
        this._pushLog("Found existing backend on port 8000 — using it.");
        this._setStatus("running");
        this._startHealthPoll();
        return;
      }
      this._pushLog(
        "Failed to start backend: Tauri runtime not initialized. " +
        "Run via 'npm run tauri dev' or a built Tauri app, not a plain browser.",
      );
      this._setStatus("error");
      return;
    }

    try {
      const isDev = import.meta.env.DEV;

      if (isDev) {
        await this._spawnDev();
      } else {
        await this._spawnProd();
      }

      this._startHealthPoll();
    } catch (e) {
      this._pushLog(`Failed to start backend: ${e}`);
      // Even if spawn failed, check if a backend is already running
      const existing = await this._probeExistingBackend();
      if (existing) {
        this._pushLog("Found existing backend on port 8000 — using it.");
        this._setStatus("running");
        this._startHealthPoll();
      } else {
        this._setStatus("error");
      }
    }
  }

  /** Probe whether a backend is already listening on port 8000. */
  private async _probeExistingBackend(): Promise<boolean> {
    try {
      const resp = await fetch("http://127.0.0.1:8000/api/health", {
        signal: AbortSignal.timeout(2000),
      });
      return resp.ok;
    } catch {
      return false;
    }
  }

  async stop(): Promise<void> {
    this._stopHealthPoll();
    if (this.process) {
      try {
        await this.process.kill();
      } catch {
        // already dead
      }
      this.process = null;
    }
    this._setStatus("stopped");
  }

  async restart(callbacks: SidecarCallbacks): Promise<void> {
    await this.stop();
    // Small delay to let the port free up
    await new Promise((r) => setTimeout(r, 500));
    await this.start(callbacks);
  }

  // --- Private ---

  private async _spawnDev(): Promise<void> {
    // In dev, spawn the venv python running the backend module.
    // Note: encoding option removed — causes transformCallback error in
    // @tauri-apps/plugin-shell v2. The plugin handles UTF-8 internally.
    const cmd = Command.create(venvPython(), [
      "-m", "backend.main",
      "--host", "127.0.0.1",
      "--port", "8000",
    ], {
      cwd: "../", // amp/ directory (parent of frontend/)
    });

    cmd.on("close", (data: TerminatedPayload) => {
      this._pushLog(`Backend exited with code ${data.code}`);
      this._setStatus("stopped");
    });

    cmd.on("error", (err: string) => {
      this._pushLog(`Backend error: ${err}`);
      this._setStatus("error");
    });

    cmd.stdout.on("data", (line: string) => this._pushLog(line));
    cmd.stderr.on("data", (line: string) => this._pushLog(line));

    this.process = await cmd.spawn();
    this._pushLog("Backend process spawned (dev mode)");
  }

  private async _spawnProd(): Promise<void> {
    // Prod: use the PyInstaller binary registered as a Tauri sidecar
    const cmd = Command.sidecar("amp-backend", [
      "--host", "127.0.0.1",
      "--port", "8000",
    ]);

    cmd.on("close", (data: TerminatedPayload) => {
      this._pushLog(`Backend exited with code ${data.code}`);
      this._setStatus("stopped");
    });

    cmd.on("error", (err: string) => {
      this._pushLog(`Backend error: ${err}`);
      this._setStatus("error");
    });

    cmd.stdout.on("data", (line: string) => this._pushLog(line));
    cmd.stderr.on("data", (line: string) => this._pushLog(line));

    this.process = await cmd.spawn();
    this._pushLog("Backend process spawned (prod mode)");
  }

  private _startHealthPoll(): void {
    this._stopHealthPoll();
    this.healthTimer = setInterval(() => this._checkHealth(), HEALTH_POLL_MS);
    // Check immediately
    this._checkHealth();
  }

  private _stopHealthPoll(): void {
    if (this.healthTimer) {
      clearInterval(this.healthTimer);
      this.healthTimer = null;
    }
  }

  private async _checkHealth(): Promise<void> {
    // P12: in-flight guard
    if (this.inFlightHealth) return;
    this.inFlightHealth = true;

    try {
      const resp = await fetch("http://127.0.0.1:8000/api/health", {
        signal: AbortSignal.timeout(3000),
      });
      if (resp.ok) {
        if (this.status !== "running") {
          this._setStatus("running");
          this._pushLog("Backend health check: OK");
        }
      } else {
        if (this.status === "running") {
          this._setStatus("error");
        }
      }
    } catch {
      if (this.status === "running") {
        this._setStatus("error");
        this._pushLog("Backend health check: FAILED");
      }
    } finally {
      this.inFlightHealth = false;
    }
  }

  private _pushLog(line: string): void {
    const trimmed = line.replace(/\n$/, "");
    this.logRing.push(trimmed);
    if (this.logRing.length > MAX_LOG_LINES) {
      this.logRing = this.logRing.slice(-MAX_LOG_LINES);
    }
    this.callbacks?.onLog(trimmed);
  }

  private _setStatus(status: BackendStatus): void {
    if (this.status !== status) {
      this.status = status;
      this.callbacks?.onStatusChange(status);
    }
  }
}

// Singleton
export const sidecar = new BackendSidecar();
